export interface ExamData {
  examCode: string;
  part1: string[]; // 12 items (A, B, C, D)
  part2: string[]; // 4 items (4-char strings like SDDS)
  part3: string[]; // 6 items (numeric strings)
}

export interface ProcessingState {
  isProcessing: boolean;
  progress: number;
  error: string | null;
  result: ExamData[] | null;
}

export interface PythonCodeParams {
  exampleData: ExamData[];
}

import * as pdfjsLib from 'pdfjs-dist';

// Use a reliable CDN for the worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

export const extractTextFromPdf = async (file: File): Promise<string> => {
  const arrayBuffer = await file.arrayBuffer();
  const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
  const pdf = await loadingTask.promise;
  let fullText = "";

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items
      .map((item: any) => item.str)
      .join(" ");
    fullText += `--- Page ${i} ---\n${pageText}\n\n`;
  }

  return fullText;
};

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "../types";

export const processExamText = async (rawText: string): Promise<ExamData[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `
      Analyze the following text extracted from a PDF which contains Vietnamese Math answer keys (Hướng dẫn chấm môn Toán).
      The text includes multiple exam codes (Mã đề).

      Rules for extraction:
      1. Part I (Phần I): 12 multiple choice questions. Extract A, B, C, or D.
      2. Part II (Phần II): 4 questions, each has 4 sub-parts (a, b, c, d) with Đ (True) or S (False).
         IMPORTANT: Combine the 4 choices into a 4-character string. Map Đ to D and S to S.
         Example: a)S, b)Đ, c)Đ, d)S becomes "SDDS".
      3. Part III (Phần III): 6 short answer questions. Extract numeric values, keeping their original decimal separators (, or .).

      Raw Text:
      ${rawText}
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            examCode: { type: Type.STRING, description: "The exam code (e.g., 0101, 1102)" },
            part1: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 12 strings (A, B, C, or D)"
            },
            part2: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 4 strings (each 4 characters long, e.g., 'SDDS')"
            },
            part3: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 6 strings (numeric answers)"
            }
          },
          required: ["examCode", "part1", "part2", "part3"]
        }
      }
    }
  });

  try {
    const data = JSON.parse(response.text);
    return data as ExamData[];
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    throw new Error("Failed to structure data from the document. Please ensure the PDF format is correct.");
  }
};

import * as XLSX from 'xlsx';
import { ExamData } from '../types';

export const exportToExcel = (data: ExamData[]) => {
  const wb = XLSX.utils.book_new();
  const ws_data: any[][] = [];

  // Header 1: Parts
  const header1 = ["", "Phần I", ...Array(11).fill(""), "Phần II", ...Array(3).fill(""), "Phần III", ...Array(5).fill("")];
  ws_data.push(header1);

  // Header 2: Question Counts
  const header2 = ["", ...Array(12).fill(12), ...Array(4).fill(4), ...Array(6).fill(6)];
  ws_data.push(header2);

  // Row 3: Exam Codes (Headers for the data columns)
  const examCodes = ["Mã đề", ...data.map(d => d.examCode)];
  ws_data.push(examCodes);

  // Rows 4-25: Question Data
  // There are 12 + 4 + 6 = 22 rows of question data
  for (let i = 0; i < 22; i++) {
    const rowLabel = i < 12 ? `Câu ${i + 1} (I)` : 
                     i < 16 ? `Câu ${i - 11} (II)` : 
                     `Câu ${i - 15} (III)`;

    const rowData = [rowLabel];

    data.forEach(exam => {
      if (i < 12) {
        rowData.push(exam.part1[i] || "");
      } else if (i < 16) {
        rowData.push(exam.part2[i - 12] || "");
      } else {
        rowData.push(exam.part3[i - 16] || "");
      }
    });

    ws_data.push(rowData);
  }

  const ws = XLSX.utils.aoa_to_sheet(ws_data);

  // Merge cells for headers
  ws['!merges'] = [
    { s: { r: 0, c: 1 }, e: { r: 0, c: 12 } }, // Phần I
    { s: { r: 0, c: 13 }, e: { r: 0, c: 16 } }, // Phần II
    { s: { r: 0, c: 17 }, e: { r: 0, c: 22 } }, // Phần III
  ];

  XLSX.utils.book_append_sheet(wb, ws, "Dữ liệu đáp án");
  XLSX.writeFile(wb, "Dap_An_Toan_Structured.xlsx");
};

