import * as pdfjsLib from 'pdfjs-dist';

// We use version 4.10.38 which is stable and widely supported.
// For modern environments using pdfjs-dist 4.0+, the worker must be loaded as an ESM module (.mjs).
const PDFJS_VERSION = '4.10.38';
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdn.jsdelivr.net/npm/pdfjs-dist@${PDFJS_VERSION}/build/pdf.worker.min.mjs`;

export const extractTextFromPdf = async (file: File): Promise<string> => {
  const arrayBuffer = await file.arrayBuffer();

  try {
    const loadingTask = pdfjsLib.getDocument({ 
      data: arrayBuffer,
      // Enabling useWorkerFetch ensures the browser uses the workerSrc provided above correctly.
      useWorkerFetch: true 
    });

    const pdf = await loadingTask.promise;
    let fullText = "";

    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items
        .map((item: any) => item.str)
        .join(" ");
      fullText += `--- Page ${i} ---\n${pageText}\n\n`;
    }

    return fullText;
  } catch (error) {
    console.error("PDF Extraction Error:", error);
    // Handle specific worker-related initialization errors gracefully.
    if (error instanceof Error && (error.message.includes("worker") || error.message.includes("module"))) {
      throw new Error("Lỗi khởi tạo bộ xử lý PDF. Vui lòng thử lại hoặc tải lại trang.");
    }
    throw new Error("Không thể trích xuất dữ liệu từ file PDF. Vui lòng đảm bảo file không bị lỗi hoặc có mật khẩu bảo vệ.");
  }
};

import * as XLSX from 'xlsx';
import { ExamData } from '../types';

export const exportToExcel = (data: ExamData[]) => {
  const wb = XLSX.utils.book_new();
  const ws_data: any[][] = [];

  // Row 1: "Số câu" and the counts
  const row1 = ["Số câu", 12, 4, 6];
  ws_data.push(row1);

  // Row 2: "Câu\Mã đề" and exam codes
  const row2 = ["Câu\\Mã đề", ...data.map(d => d.examCode)];
  ws_data.push(row2);

  // Rows for Part I (12 questions)
  for (let i = 0; i < 12; i++) {
    const row = [i + 1, ...data.map(exam => exam.part1[i] || "")];
    ws_data.push(row);
  }

  // Rows for Part II (4 questions)
  for (let i = 0; i < 4; i++) {
    const row = [i + 1, ...data.map(exam => exam.part2[i] || "")];
    ws_data.push(row);
  }

  // Rows for Part III (6 questions)
  for (let i = 0; i < 6; i++) {
    const row = [i + 1, ...data.map(exam => exam.part3[i] || "")];
    ws_data.push(row);
  }

  const ws = XLSX.utils.aoa_to_sheet(ws_data);

  // Note: Standard 'xlsx' community edition does not support cell background colors.
  // The structure and values will strictly match the requested layout.

  XLSX.utils.book_append_sheet(wb, ws, "Dữ liệu đáp án");
  XLSX.writeFile(wb, "Dap_An_Toan_Chinh_Thuc.xlsx");
};

