import * as XLSX from 'xlsx';
import { ExamData } from '../types';

export const exportToExcel = (data: ExamData[]) => {
  const wb = XLSX.utils.book_new();
  const ws_data: any[][] = [];

  // Hàng 1: "Số câu" và các giá trị 12, 4, 6
  const row1 = ["Số câu", 12, 4, 6];
  // Nếu có nhiều mã đề hơn 3, thêm các ô trống
  if (data.length > 3) {
    for (let i = 0; i < data.length - 3; i++) row1.push("");
  }
  ws_data.push(row1);

  // Hàng 2: "Câu\Mã đề" và danh sách mã đề
  const row2 = ["Câu\\Mã đề", ...data.map(d => d.examCode)];
  ws_data.push(row2);

  // Nhóm các hàng cho Phần I (12 câu)
  for (let i = 0; i < 12; i++) {
    const row = [i + 1, ...data.map(exam => exam.part1[i] || "")];
    ws_data.push(row);
  }

  // Nhóm các hàng cho Phần II (4 câu)
  for (let i = 0; i < 4; i++) {
    const row = [i + 1, ...data.map(exam => exam.part2[i] || "")];
    ws_data.push(row);
  }

  // Nhóm các hàng cho Phần III (6 câu)
  for (let i = 0; i < 6; i++) {
    const row = [i + 1, ...data.map(exam => exam.part3[i] || "")];
    ws_data.push(row);
  }

  const ws = XLSX.utils.aoa_to_sheet(ws_data);

  // Cấu hình độ rộng cột cho đẹp
  const wscols = [
    { wch: 15 }, // Cột A
    ...data.map(() => ({ wch: 12 })) // Các cột mã đề
  ];
  ws['!cols'] = wscols;

  XLSX.utils.book_append_sheet(wb, ws, "Dap An Chuan");
  XLSX.writeFile(wb, "Dap_An_Toan_Chinh_Thuc.xlsx");
};

import * as XLSX from 'xlsx';
import { ExamData } from '../types';

export const exportToExcel = (data: ExamData[]) => {
  const wb = XLSX.utils.book_new();
  const ws: any = {};

  // Cấu hình Style
  const borderStyle = {
    top: { style: "thin", color: { rgb: "000000" } },
    bottom: { style: "thin", color: { rgb: "000000" } },
    left: { style: "thin", color: { rgb: "000000" } },
    right: { style: "thin", color: { rgb: "000000" } }
  };

  const baseStyle = {
    font: { name: "Times New Roman", sz: 11 },
    alignment: { vertical: "center", horizontal: "center" },
    border: borderStyle
  };

  const headerStyle = {
    ...baseStyle,
    font: { ...baseStyle.font, bold: true }
  };

  const part1Style = { ...headerStyle, fill: { fgColor: { rgb: "FFF2CC" } } };
  const part2Style = { ...headerStyle, fill: { fgColor: { rgb: "E2EFDA" } } };
  const part3Style = { ...headerStyle, fill: { fgColor: { rgb: "C6E0B4" } } };

  // Hàm helper để gán cell
  const setCell = (r: number, c: number, value: any, style: any = baseStyle) => {
    const cellRef = XLSX.utils.encode_cell({ r, c });
    ws[cellRef] = { v: value, s: style, t: typeof value === 'number' ? 'n' : 's' };
  };

  // Hàng 1: Số câu
  setCell(0, 0, "Số câu", headerStyle);
  setCell(0, 1, 12, part1Style);
  setCell(0, 2, 4, part2Style);
  setCell(0, 3, 6, part3Style);
  // Fill empty cells in row 1 if more exam codes exist
  for (let j = 4; j <= data.length; j++) {
    setCell(0, j, "", baseStyle);
  }

  // Hàng 2: Câu\Mã đề
  setCell(1, 0, "Câu\\Mã đề", part1Style);
  data.forEach((exam, idx) => {
    setCell(1, idx + 1, exam.examCode, headerStyle);
  });

  let currentRow = 2;

  // Phần I: 12 câu
  for (let i = 0; i < 12; i++) {
    setCell(currentRow, 0, i + 1, part1Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part1[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Phần II: 4 câu
  for (let i = 0; i < 4; i++) {
    setCell(currentRow, 0, i + 1, part2Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part2[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Phần III: 6 câu
  for (let i = 0; i < 6; i++) {
    setCell(currentRow, 0, i + 1, part3Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part3[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Cấu hình dải ô (Range)
  ws['!ref'] = XLSX.utils.encode_range({
    s: { r: 0, c: 0 },
    e: { r: currentRow - 1, c: data.length }
  });

  // Độ rộng cột
  ws['!cols'] = [
    { wch: 15 }, // Cột A
    ...data.map(() => ({ wch: 10 }))
  ];

  XLSX.utils.book_append_sheet(wb, ws, "Dap An Toan");
  XLSX.writeFile(wb, "Dap_An_Toan_Chinh_Thuc.xlsx");
};

import XLSX from 'xlsx';
import { ExamData } from '../types';

export const exportToExcel = (data: ExamData[]) => {
  if (!XLSX || !XLSX.utils) {
    console.error("XLSX library not loaded correctly");
    return;
  }

  const wb = XLSX.utils.book_new();
  const ws: any = {};

  // Cấu hình Style
  const borderStyle = {
    top: { style: "thin", color: { rgb: "000000" } },
    bottom: { style: "thin", color: { rgb: "000000" } },
    left: { style: "thin", color: { rgb: "000000" } },
    right: { style: "thin", color: { rgb: "000000" } }
  };

  const baseStyle = {
    font: { name: "Times New Roman", sz: 11 },
    alignment: { vertical: "center", horizontal: "center" },
    border: borderStyle
  };

  const headerStyle = {
    ...baseStyle,
    font: { ...baseStyle.font, bold: true }
  };

  const part1Style = { ...headerStyle, fill: { fgColor: { rgb: "FFF2CC" } } };
  const part2Style = { ...headerStyle, fill: { fgColor: { rgb: "E2EFDA" } } };
  const part3Style = { ...headerStyle, fill: { fgColor: { rgb: "C6E0B4" } } };

  // Hàm helper để gán cell
  const setCell = (r: number, c: number, value: any, style: any = baseStyle) => {
    const cellRef = XLSX.utils.encode_cell({ r, c });
    ws[cellRef] = { v: value, s: style, t: typeof value === 'number' ? 'n' : 's' };
  };

  // Hàng 1: Số câu
  setCell(0, 0, "Số câu", headerStyle);
  setCell(0, 1, 12, part1Style);
  setCell(0, 2, 4, part2Style);
  setCell(0, 3, 6, part3Style);

  // Fill empty cells in row 1 if more exam codes exist
  for (let j = 4; j <= data.length; j++) {
    setCell(0, j, "", baseStyle);
  }

  // Hàng 2: Câu\Mã đề
  setCell(1, 0, "Câu\\Mã đề", part1Style);
  data.forEach((exam, idx) => {
    setCell(1, idx + 1, exam.examCode, headerStyle);
  });

  let currentRow = 2;

  // Phần I: 12 câu
  for (let i = 0; i < 12; i++) {
    setCell(currentRow, 0, i + 1, part1Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part1[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Phần II: 4 câu
  for (let i = 0; i < 4; i++) {
    setCell(currentRow, 0, i + 1, part2Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part2[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Phần III: 6 câu
  for (let i = 0; i < 6; i++) {
    setCell(currentRow, 0, i + 1, part3Style);
    data.forEach((exam, idx) => {
      setCell(currentRow, idx + 1, exam.part3[i] || "", baseStyle);
    });
    currentRow++;
  }

  // Cấu hình dải ô (Range)
  ws['!ref'] = XLSX.utils.encode_range({
    s: { r: 0, c: 0 },
    e: { r: currentRow - 1, c: data.length }
  });

  // Độ rộng cột
  ws['!cols'] = [
    { wch: 15 }, // Cột A
    ...data.map(() => ({ wch: 10 }))
  ];

  XLSX.utils.book_append_sheet(wb, ws, "Dap An Toan");
  XLSX.writeFile(wb, "Dap_An_Toan_Chinh_Thuc.xlsx");
};

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "../types";

export const processExamText = async (rawText: string): Promise<ExamData[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `
      Analyze the following text extracted from a PDF which contains Vietnamese exam answer keys (Hướng dẫn chấm).
      The text includes multiple exam codes (Mã đề).

      Rules for extraction:
      1. Part I (Phần I): 18 multiple choice questions. Extract A, B, C, or D.
      2. Part II (Phần II): 4 questions, each has 4 sub-parts (a, b, c, d) with Đ (True) or S (False).
         IMPORTANT: Combine the 4 choices into a 4-character string. Map Đ to D and S to S.
         Example: a)S, b)Đ, c)Đ, d)S becomes "SDDS".
      3. Part III (Phần III): 6 short answer questions. Extract numeric values, keeping their original decimal separators (, or .).

      Raw Text:
      ${rawText}
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            examCode: { type: Type.STRING, description: "The exam code (e.g., 0101, 1102)" },
            part1: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 18 strings (A, B, C, or D)"
            },
            part2: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 4 strings (each 4 characters long, e.g., 'SDDS')"
            },
            part3: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of 6 strings (numeric answers)"
            }
          },
          required: ["examCode", "part1", "part2", "part3"]
        }
      }
    }
  });

  try {
    const data = JSON.parse(response.text);
    return data as ExamData[];
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    throw new Error("Failed to structure data from the document. Please ensure the PDF format is correct.");
  }
};

