import React, { useState } from 'react';
import { Upload, FileSpreadsheet, AlertCircle, Loader2, CheckCircle2, RefreshCw } from 'lucide-react';
import { extractTextFromPdf } from './services/pdfService';
import { processExamText } from './services/geminiService';
import { exportToExcel } from './services/excelService';
import { ProcessingState } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<ProcessingState>({
    isProcessing: false,
    progress: 0,
    error: null,
    result: null,
  });

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setState(prev => ({ ...prev, error: "Vui lòng chọn file PDF." }));
      return;
    }

    setState({ isProcessing: true, progress: 10, error: null, result: null });

    try {
      setState(prev => ({ ...prev, progress: 30 }));
      const rawText = await extractTextFromPdf(file);

      setState(prev => ({ ...prev, progress: 60 }));
      const structuredData = await processExamText(rawText);

      setState({
        isProcessing: false,
        progress: 100,
        error: null,
        result: structuredData
      });
    } catch (err: any) {
      console.error(err);
      setState({
        isProcessing: false,
        progress: 0,
        error: err.message || "Đã có lỗi xảy ra trong quá trình xử lý.",
        result: null
      });
    }
  };

  const handleDownload = () => {
    if (state.result) {
      exportToExcel(state.result);
    }
  };

  const reset = () => {
    setState({
      isProcessing: false,
      progress: 0,
      error: null,
      result: null
    });
  };

  return (
    <div className="min-h-screen bg-[#f0f2f5] p-4 md:p-8">
      <div className="max-w-6xl mx-auto">
        <header className="mb-6 text-center">
          <h1 className="text-2xl font-bold text-slate-800 flex items-center justify-center gap-2">
            <FileSpreadsheet className="text-green-700" size={28} /> 
            Hệ thống trích xuất đáp án
          </h1>
        </header>

        <main>
          {!state.result && !state.isProcessing && (
            <div className="max-w-xl mx-auto bg-white rounded-xl shadow-md border border-slate-200 p-8">
              <label className="flex flex-col items-center justify-center border-2 border-dashed border-slate-300 rounded-lg p-12 cursor-pointer hover:bg-slate-50 transition-all">
                <Upload className="text-slate-400 mb-4" size={48} />
                <span className="text-slate-700 font-semibold text-lg">Tải file PDF đáp án lên</span>
                <p className="text-slate-400 text-sm mt-2">Phần I (18 câu), Phần II (4 câu), Phần III (6 câu)</p>
                <input type="file" className="hidden" accept=".pdf" onChange={handleFileUpload} />
              </label>
              {state.error && (
                <div className="mt-4 p-4 bg-red-50 text-red-600 rounded-lg flex items-center gap-3 border border-red-100 shadow-sm">
                  <AlertCircle size={20} /> <span className="font-medium">{state.error}</span>
                </div>
              )}
            </div>
          )}

          {state.isProcessing && (
            <div className="max-w-md mx-auto bg-white rounded-xl shadow-lg p-10 text-center">
              <div className="relative inline-block mb-4">
                <Loader2 className="animate-spin text-green-600" size={56} />
                <div className="absolute inset-0 flex items-center justify-center text-xs font-bold text-green-700">
                  {state.progress}%
                </div>
              </div>
              <p className="text-slate-700 font-bold text-lg">Đang phân tích cấu trúc đáp án...</p>
              <p className="text-slate-400 text-sm">Vui lòng đợi trong giây lát</p>
            </div>
          )}

          {state.result && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white rounded-lg shadow-xl border border-slate-300 overflow-hidden">
                <div className="p-4 bg-slate-100 border-b border-slate-300 flex justify-between items-center">
                  <span className="font-bold text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                    <CheckCircle2 size={20} className="text-green-600" /> Bảng đáp án chi tiết (18-4-6)
                  </span>
                  <div className="flex gap-2">
                    <button onClick={reset} className="px-3 py-1.5 text-slate-500 hover:text-slate-700 hover:bg-slate-200 rounded transition-all flex items-center gap-1.5 text-sm font-semibold">
                      <RefreshCw size={16} /> Nhập file mới
                    </button>
                    <button onClick={handleDownload} className="bg-green-700 text-white px-5 py-2 rounded font-bold flex items-center gap-2 hover:bg-green-800 transition-all shadow-md">
                      <FileSpreadsheet size={18} /> Tải file Excel (.xlsx)
                    </button>
                  </div>
                </div>

                <div className="overflow-x-auto p-4 bg-white">
                  <table className="w-full text-[13px] border-collapse border-[1.5px] border-black font-sans">
                    <thead>
                      {/* Row 1: Số câu */}
                      <tr>
                        <td className="border border-black px-4 py-1.5 font-bold text-center bg-white min-w-[120px]">Số câu</td>
                        <td className="border border-black px-4 py-1.5 font-bold text-center bg-[#FFF2CC]">18</td>
                        <td className="border border-black px-4 py-1.5 font-bold text-center bg-[#E2EFDA]">4</td>
                        <td className="border border-black px-4 py-1.5 font-bold text-center bg-[#C6E0B4]">6</td>
                        {state.result.length > 3 && (
                           Array.from({ length: state.result.length - 3 }).map((_, i) => (
                             <td key={i} className="border border-black bg-white"></td>
                           ))
                        )}
                      </tr>
                      {/* Row 2: Mã đề */}
                      <tr className="bg-white font-bold">
                        <td className="border border-black px-4 py-1.5 text-center bg-[#FFF2CC]">Câu\Mã đề</td>
                        {state.result.map(exam => (
                          <td key={exam.examCode} className="border border-black px-4 py-1.5 text-center text-black">
                            {exam.examCode}
                          </td>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {/* Part I: 1-18 (Yellow) */}
                      {Array.from({ length: 18 }).map((_, i) => (
                        <tr key={`p1-${i}`}>
                          <td className="border border-black px-4 py-0.5 text-center bg-[#FFF2CC] font-bold">{i + 1}</td>
                          {state.result?.map(exam => (
                            <td key={exam.examCode} className="border border-black px-4 py-0.5 text-center bg-white font-medium">
                              {exam.part1[i] || ''}
                            </td>
                          ))}
                        </tr>
                      ))}
                      {/* Part II: 1-4 (Light Green) */}
                      {Array.from({ length: 4 }).map((_, i) => (
                        <tr key={`p2-${i}`}>
                          <td className="border border-black px-4 py-0.5 text-center bg-[#E2EFDA] font-bold">{i + 1}</td>
                          {state.result?.map(exam => (
                            <td key={exam.examCode} className="border border-black px-4 py-0.5 text-center bg-white font-medium">
                              {exam.part2[i] || ''}
                            </td>
                          ))}
                        </tr>
                      ))}
                      {/* Part III: 1-6 (Green) */}
                      {Array.from({ length: 6 }).map((_, i) => (
                        <tr key={`p3-${i}`}>
                          <td className="border border-black px-4 py-0.5 text-center bg-[#C6E0B4] font-bold">{i + 1}</td>
                          {state.result?.map(exam => (
                            <td key={exam.examCode} className="border border-black px-4 py-0.5 text-center bg-white font-medium">
                              {exam.part3[i] || ''}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

