import { GoogleGenAI, Type } from "@google/genai";
import { ExamData, SubjectConfig } from "../types";

export const processExamText = async (rawText: string, config: SubjectConfig): Promise<ExamData[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let rules = `Rules for extraction for subject ${config.name}:\n`;
  rules += `1. Part I: ${config.p1Count} multiple choice questions (A, B, C, or D).\n`;
  if (config.p2Count > 0) {
    rules += `2. Part II: ${config.p2Count} questions, each has 4 sub-parts (a, b, c, d) with Đ (True) or S (False). Combine into a 4-char string (e.g., "SDDS").\n`;
  } else {
    rules += `2. Part II: No questions. Return an empty array.\n`;
  }
  if (config.p3Count > 0) {
    rules += `3. Part III: ${config.p3Count} short answer questions. Extract numeric values.\n`;
  } else {
    rules += `3. Part III: No questions. Return an empty array.\n`;
  }

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `
      Analyze the following text from a PDF of Vietnamese exam answer keys.
      Extract data for all Exam Codes (Mã đề) found.

      ${rules}

      Raw Text:
      ${rawText}
    `,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            examCode: { type: Type.STRING },
            part1: { type: Type.ARRAY, items: { type: Type.STRING } },
            part2: { type: Type.ARRAY, items: { type: Type.STRING } },
            part3: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["examCode", "part1", "part2", "part3"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text) as ExamData[];
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    throw new Error("Không thể cấu trúc hóa dữ liệu. Vui lòng kiểm tra định dạng PDF.");
  }
};

import XLSX from 'xlsx';
import { ExamData, SubjectConfig } from '../types';

export const exportToExcel = (data: ExamData[], config: SubjectConfig) => {
  if (!XLSX || !XLSX.utils) return;

  const wb = XLSX.utils.book_new();
  const ws: any = {};

  const borderStyle = {
    top: { style: "thin", color: { rgb: "000000" } },
    bottom: { style: "thin", color: { rgb: "000000" } },
    left: { style: "thin", color: { rgb: "000000" } },
    right: { style: "thin", color: { rgb: "000000" } }
  };

  const baseStyle = {
    font: { name: "Times New Roman", sz: 11 },
    alignment: { vertical: "center", horizontal: "center" },
    border: borderStyle
  };

  const headerStyle = { ...baseStyle, font: { ...baseStyle.font, bold: true } };
  const p1Style = { ...headerStyle, fill: { fgColor: { rgb: "FFF2CC" } } };
  const p2Style = { ...headerStyle, fill: { fgColor: { rgb: "E2EFDA" } } };
  const p3Style = { ...headerStyle, fill: { fgColor: { rgb: "C6E0B4" } } };

  const setCell = (r: number, c: number, value: any, style: any = baseStyle) => {
    const cellRef = XLSX.utils.encode_cell({ r, c });
    ws[cellRef] = { v: value, s: style, t: typeof value === 'number' ? 'n' : 's' };
  };

  // Row 1: Counts
  setCell(0, 0, "Số câu", headerStyle);
  setCell(0, 1, config.p1Count, p1Style);
  if (config.p2Count > 0) setCell(0, 2, config.p2Count, p2Style);
  if (config.p3Count > 0) setCell(0, 3, config.p3Count, p3Style);

  // Row 2: Header
  setCell(1, 0, "Câu\\Mã đề", p1Style);
  data.forEach((exam, idx) => setCell(1, idx + 1, exam.examCode, headerStyle));

  let currentRow = 2;

  // Part I
  for (let i = 0; i < config.p1Count; i++) {
    setCell(currentRow, 0, i + 1, p1Style);
    data.forEach((exam, idx) => setCell(currentRow, idx + 1, exam.part1[i] || "", baseStyle));
    currentRow++;
  }

  // Part II
  for (let i = 0; i < config.p2Count; i++) {
    setCell(currentRow, 0, i + 1, p2Style);
    data.forEach((exam, idx) => setCell(currentRow, idx + 1, exam.part2[i] || "", baseStyle));
    currentRow++;
  }

  // Part III
  for (let i = 0; i < config.p3Count; i++) {
    setCell(currentRow, 0, i + 1, p3Style);
    data.forEach((exam, idx) => setCell(currentRow, idx + 1, exam.part3[i] || "", baseStyle));
    currentRow++;
  }

  ws['!ref'] = XLSX.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: currentRow - 1, c: data.length } });
  ws['!cols'] = [{ wch: 15 }, ...data.map(() => ({ wch: 10 }))];

  XLSX.utils.book_append_sheet(wb, ws, "Dap An");
  XLSX.writeFile(wb, `Dap_An_${config.id}.xlsx`);
};

